<!DOCTYPE html><html lang="en"><head><meta charset="UTF-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Reset password - <?php echo htmlspecialchars(SITENAME); ?></title><style>body{font-family:Arial,sans-serif;background:#f1f5f9;display:grid;place-items:center;min-height:100vh;margin:0}.card{background:#fff;padding:32px;border-radius:16px;max-width:440px;width:calc(100% - 48px)}input,button{box-sizing:border-box;width:100%;padding:12px;margin-top:10px}button{background:#0f766e;color:#fff;border:0}a{color:#0f766e}.dev-reset{background:#ecfeff;border:1px solid #99f6e4;border-radius:10px;margin-top:16px;padding:12px;word-break:break-word}.dev-reset strong{display:block;margin-bottom:6px}</style></head><body><main class="card"><h1>Reset password</h1><?php if ($message): ?><p><?php echo htmlspecialchars($message); ?></p><?php if (!empty($developmentResetUrl) && APP_ENV !== 'production'): ?><p class="dev-reset"><strong>Local development reset link</strong><a href="<?php echo htmlspecialchars($developmentResetUrl, ENT_QUOTES, 'UTF-8'); ?>"><?php echo htmlspecialchars($developmentResetUrl); ?></a></p><?php endif; ?><?php else: ?><p>Enter your account email address.</p><form method="post"><?php echo csrfInput(); ?><input type="email" name="email" autocomplete="email" required><button type="submit">Send reset instructions</button></form><?php endif; ?><p><a href="<?php echo URLROOT; ?>/auth/login">Back to login</a></p></main></body></html>
